        const scopedToolDefinitions = filterProjectScopedRemoteToolDefinitions(normalizeToolDefinitions(input.source.id, await input.source.listTools(sourceContext)), activeProjectId, input.projectScopedRemoteToolOptions);
        const toolDefinitions = input.filterToolDefinitions
            ? await input.filterToolDefinitions({
                source: input.source,
                toolDefinitions: scopedToolDefinitions,
                activeProjectId,
                context: sourceContext,
            })
            : scopedToolDefinitions;
